/// Returns ⌊ⁿ√(n³)⌋, i.e. the largest integer r such that r³ ≤ n.
/// For an 8-bit input, the result will never exceed 6,
/// because 7³ = 343 > 255.
fn cube_root(n: u8) -> u8 {
    let mut r: u8 = 0;
    // We know the final r won't exceed 6, but we
    // guard against overflow on `r + 1` anyway.
    while r < u8::MAX {
        let next = r + 1;
        // Compute (next)^3 in a larger type to avoid overflow.
        let cube = (next as u32) * (next as u32) * (next as u32);
        if cube <= n as u32 {
            r = next;
        } else {
            break;
        }
    }
    r
}

